R=Path(__file__).resolve().parents[1];d=json.loads((R/'data/purchase-stage-content.json').read_text())
paths={'blanco':'<path d="M5 3h10l4 4v14H5zM15 3v5h4M8 12h8M8 16h5"/>','verde':'<path d="M3 21h18M5 21V8h10v13M8 11h1m3 0h1M8 15h1m3 0h1M9 21v-3h3M3 4h18M17 4v6M5 4V2M14 4V2"/>','inmediata':'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-7h6v7M9 10h6"/>'}
