head='''<!DOCTYPE html><html lang="es-CL"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>¿Comprar en blanco, en verde o con entrega inmediata? | Sollahms</title><meta name="description" content="Compara las etapas de compra de una vivienda en Chile. Conoce ventajas y riesgos, responde cuatro preguntas sin datos personales y explora proyectos de Sollahms."><link rel="canonical" href="https://sollahms.cl/cuando-comprar-propiedad.html"><link rel="icon" type="image/svg+xml" href="/assets/branding/favicon.svg?v=20261026-logo-1"><meta property="og:type" content="website"><meta property="og:title" content="¿Comprar en blanco, en verde o con entrega inmediata? | Sollahms"><meta property="og:description" content="Compara con claridad. Descubre qué etapa puede acomodarse a tu plazo y tus prioridades."><meta property="og:url" content="https://sollahms.cl/cuando-comprar-propiedad.html"><meta property="og:image" content="https://sollahms.cl/assets/branding/og-sollahms-square-v3.png"><meta property="og:locale" content="es_CL"><link rel="stylesheet" href="/assets/css/contacto.tailwind.css"><link rel="stylesheet" href="/assets/css/home-seo.css?v=20261025-visual-1"><link rel="stylesheet" href="/assets/css/purchase-stage.css?v=20261029-1"><link rel="stylesheet" href="/assets/css/sollahms-brand.css?v=20261026-1"><link rel="stylesheet" href="/assets/css/sollahms-theme.css?v=20261026-scroll-3"><script src="/assets/js/scroll-presence.js?v=20261026-3" defer></script></head><body class="ps-page"><a class="home-skip-link" href="#contenido-principal">Saltar al contenido</a>'''
journey='<ol class="ps-journey">'+''.join('<li>'+icon(s['id'])+'<a href="#'+s['id']+'"><strong>'+e(s['title'])+'</strong><small>'+e(s['short'])+'</small></a></li>' for s in d['stages'])+'</ol>'
